 async Task LoadAvailable(){if(selectedChoice==null){Status("Selecione um mapa. O nome do alvo aparece ao lado de Rodadas.",true);return;}var chosen=selectedChoice;await PlayChosenMap(chosen.Map,chosen.Mode,chosen.Rounds);}
 async Task Switch(){if(rotation.SelectedIndices.Count==0){Status("Selecione um mapa da rotação.",true);return;}var entry=draft[rotation.SelectedIndices[0]];if(!BotMaps.Supported(entry.Map,entry.Mode)&&!botsPanel.Confirm("Mapa sem suporte de bots confirmado",BotMaps.Warning(entry.Map,entry.Mode),"Carregar mesmo assim"))return;await LoadChoice(entry);}
 async Task LoadChoice(RotationEntry choice){if(busy)return;string host=rconHost.Text.Trim(),secret=password.Text;int selectedPort=(int)port.Value;var pending=dirty?Copy(draft):null;await Work("Preparando "+MapOption.NameOf(choice.Map)+" no servidor offline…",async()=>{Rcon next=null;try{var progress=Progress();var result=await Task.Run(()=>{if(pending!=null){string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BF4BotLauncher","draft-backups");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,DateTime.Now.ToString("yyyyMMdd-HHmmssfff")+".json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(pending));}if(host=="127.0.0.1"){OneClick.PrepareLocal(root,progress);OneClick.HideHelpers(root);}next=new Rcon();next.Connect(host,selectedPort,secret);var live=next.Maps();var wanted=MapNow.Exclusive(choice);string backup=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BF4BotLauncher","rotation-backups",DateTime.Now.ToString("yyyyMMdd-HHmmssfff")+"-carregar.json");bool localServer=LocalRotation.Matches(root,host,selectedPort);if(!Rcon.Same(live,wanted)){if(localServer)LocalRotation.Save(root,next,live,wanted,backup);else next.SaveRotation(live,wanted,backup);}progress("Carregando "+MapOption.NameOf(choice.Map)+"; aguardando confirmação do servidor…");MapNow.SwitchAndWait(next,choice,"Offline - "+MapOption.NameOf(choice.Map));if(localServer)LocalRotation.SaveName(root,"Offline - "+MapOption.NameOf(choice.Map));return wanted;});if(rcon!=null)rcon.Dispose();rcon=next;next=null;baseline=Copy(result);draft=Copy(result);dirty=false;DrawRotation();if(rotation.Items.Count>0)rotation.Items[0].Selected=true;serverState.Text="Ativo: "+MapOption.NameOf(choice.Map);Status("Mapa confirmado: "+MapOption.NameOf(choice.Map)+". No BF4, atualize a lista e entre em Offline - "+MapOption.NameOf(choice.Map)+". Se já estiver na partida, aguarde a transição."+(pending!=null?" A edição anterior da rotação foi guardada em backup.":""));WriteReport("map-now.txt","Mapa e modo confirmados no servidor: "+choice.Map+" / "+choice.Mode+". Nome: Offline - "+MapOption.NameOf(choice.Map));}finally{if(next!=null)next.Dispose();}});}

}
public static class UnifiedProgram {
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr window,uint message,IntPtr w,IntPtr l);
 [STAThread]public static int Main(string[]args){if(args.Length>0&&args[0]=="--recover-rotation")return UnifiedTests.RecoverRotation(args[1]);if(args.Length>0&&args[0]=="--map-now-live")return UnifiedTests.LoadMapLive(args[1]);if(args.Length>0&&args[0]=="--offline-test")return OneClick.Test(args[1]);if(args.Length>0&&args[0]=="--unified-test")return UnifiedTests.Run(args[1]);if(args.Length>0&&args[0]=="--rcon-read-test")return UnifiedTests.Live(args[1]);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root;try{root=InstallPath.Resolve(args);if(root==null)return 0;}catch(Exception ex){MessageBox.Show(ex.Message,"BF4 — localizar instalação",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}try{bool created;using(var single=new Mutex(true,"Local\\BF4Central_UI_"+Config.Hash(Encoding.UTF8.GetBytes(root.ToLowerInvariant())).Substring(0,12),out created)){if(!created){foreach(var p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(Application.ExecutablePath))){if(p.Id==Process.GetCurrentProcess().Id)continue;try{if(OneClick.SamePath(p.MainModule.FileName,Application.ExecutablePath)){OneClick.Focus(p);if(args.Contains("--play"))PostMessage(p.MainWindowHandle,0x8031,IntPtr.Zero,IntPtr.Zero);}}catch{}}return 0;}try{var form=new Central(root);int selectedMap=Array.IndexOf(args,"--map");if(args.Contains("--locker-repair"))form.Shown+=async(s,e)=>await form.PrioritizeLocker();else if(selectedMap>=0&&selectedMap+1<args.Length){string id=args[selectedMap+1];form.Shown+=async(s,e)=>await form.PlayChosenMap(id,"ConquestLarge0");}else if(args.Contains("--play"))form.Shown+=async(s,e)=>await form.StartAll();else if(args.Contains("--server"))form.Shown+=async(s,e)=>await form.ShowServer();Application.Run(form);return 0;}finally{single.ReleaseMutex();}}}catch(Exception ex){MessageBox.Show(ex.Message,"BF4 — não foi possível abrir",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
}
}
